package application_test
import ("context"; "os"; "path/filepath"; "testing"; "time"; "evidence/internal/application"; "evidence/internal/domain"; "evidence/internal/repository")
func TestBug06RepeatEnableRejectedWithoutDuplicate(t *testing.T){ctx:=context.Background(); root:=t.TempDir(); repo,_:=repository.NewFileRepository(root); exp:=time.Now().Add(time.Hour); _=repo.SaveConditionVersion(ctx,domain.ConditionVersion{ID:"cv",RequestID:"r",Scope:domain.ResourceScope{Type:"doc",Identifier:"x"}}); _=repo.SaveRequest(ctx,domain.AuthorizationRequest{ID:"r",Status:domain.StatusUnderReview,CurrentVersionID:"cv",ExpiresAt:&exp,Version:1}); svc:=application.NewAuthorizationService(repo); if err:=svc.Enable(ctx,"r","u");err!=nil{t.Fatal(err)}; if err:=svc.Enable(ctx,"r","u");err==nil{t.Fatal("repeat enable succeeded")}; got,_:=repo.GetRequest(ctx,"r"); files,_:=os.ReadDir(filepath.Join(root,"decisions")); if got.Version!=2||len(files)!=1{t.Fatalf("version=%d decisions=%d",got.Version,len(files))}}
